-- Admin inbox starts at deployment; no historical rows or financial documents are modified.
CREATE TABLE IF NOT EXISTS public."AdminNotification" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "category" TEXT NOT NULL CHECK ("category" IN ('crm','club','orders','campaigns')),
 "kind" TEXT NOT NULL,
 "sourceKey" TEXT NOT NULL UNIQUE,
 "userId" INTEGER,
 "orderId" INTEGER,
 "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "AdminNotification_category_createdAt_idx"
  ON public."AdminNotification" ("category","createdAt" DESC);
CREATE INDEX IF NOT EXISTS "AdminNotification_createdAt_idx"
  ON public."AdminNotification" ("createdAt" DESC);
CREATE TABLE IF NOT EXISTS public."AdminNotificationSeen" (
 "adminId" INTEGER NOT NULL REFERENCES public."User"(id) ON DELETE CASCADE,
 "notificationId" BIGINT NOT NULL REFERENCES public."AdminNotification"(id) ON DELETE CASCADE,
 "seenAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 PRIMARY KEY("adminId","notificationId")
);
CREATE INDEX IF NOT EXISTS "AdminNotificationSeen_adminId_idx" ON public."AdminNotificationSeen" ("adminId");
ALTER TABLE public."AdminNotification" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."AdminNotificationSeen" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."AdminNotification",public."AdminNotificationSeen" FROM anon,authenticated;

-- Do not create an externally callable notification writer. Event functions are
-- trigger-only (TRIGGER return type) with invoker privileges and fixed search path.
CREATE OR REPLACE FUNCTION public.notify_customer_registration() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
   VALUES ('crm','registered','user:'||NEW.id||':registered',NEW.id) ON CONFLICT ("sourceKey") DO NOTHING;
 ELSIF OLD.verified IS NULL AND NEW.verified IS NOT NULL THEN
  INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
   VALUES ('crm','email_verified','user:'||NEW.id||':verified',NEW.id) ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_customer_registration() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_user ON public."User";
CREATE TRIGGER admin_notify_user AFTER INSERT OR UPDATE OF verified ON public."User"
 FOR EACH ROW EXECUTE FUNCTION public.notify_customer_registration();

CREATE OR REPLACE FUNCTION public.notify_newsletter_consent() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NEW."marketingRequestedAt" IS NOT NULL
   AND (TG_OP='INSERT' OR OLD."marketingRequestedAt" IS DISTINCT FROM NEW."marketingRequestedAt") THEN
   INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
    VALUES ('crm','newsletter_requested','consent:'||NEW."userId"||':requested:'||extract(epoch from NEW."marketingRequestedAt")::text,NEW."userId")
    ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 IF NEW."marketingConfirmedAt" IS NOT NULL
   AND (TG_OP='INSERT' OR OLD."marketingConfirmedAt" IS NULL) THEN
   INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
    VALUES ('crm','newsletter_confirmed','consent:'||NEW."userId"||':confirmed:'||extract(epoch from NEW."marketingConfirmedAt")::text,NEW."userId")
    ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 IF NEW."marketingWithdrawnAt" IS NOT NULL
   AND (TG_OP='INSERT' OR OLD."marketingWithdrawnAt" IS NULL) THEN
   INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
    VALUES ('crm','newsletter_unsubscribed','consent:'||NEW."userId"||':withdrawn:'||extract(epoch from NEW."marketingWithdrawnAt")::text,NEW."userId")
    ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_newsletter_consent() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_consent ON public."AccountConsent";
CREATE TRIGGER admin_notify_consent AFTER INSERT OR UPDATE OF "marketingRequestedAt","marketingConfirmedAt","marketingWithdrawnAt"
 ON public."AccountConsent" FOR EACH ROW EXECUTE FUNCTION public.notify_newsletter_consent();

CREATE OR REPLACE FUNCTION public.notify_legacy_coupon() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NEW."grantedAt" IS NOT NULL AND (TG_OP='INSERT' OR OLD."grantedAt" IS NULL) THEN
  INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
   VALUES ('club','coupon_issued','reward:'||NEW."userId"||':issued',NEW."userId")
   ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 IF NEW."emailSentAt" IS NOT NULL AND (TG_OP='INSERT' OR OLD."emailSentAt" IS NULL) THEN
  INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId")
   VALUES ('campaigns','coupon_email_sent','reward:'||NEW."userId"||':emailed',NEW."userId")
   ON CONFLICT ("sourceKey") DO NOTHING;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_legacy_coupon() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_legacy_coupon ON public."LegacyNewsletterReward";
CREATE TRIGGER admin_notify_legacy_coupon AFTER INSERT OR UPDATE OF "grantedAt","emailSentAt"
 ON public."LegacyNewsletterReward" FOR EACH ROW EXECUTE FUNCTION public.notify_legacy_coupon();

CREATE OR REPLACE FUNCTION public.notify_order_created() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId","orderId")
 VALUES ('orders','new_order','order:'||NEW.id||':created',NEW."userId",NEW.id)
 ON CONFLICT ("sourceKey") DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_order_created() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_order ON public."Order";
CREATE TRIGGER admin_notify_order AFTER INSERT ON public."Order"
 FOR EACH ROW EXECUTE FUNCTION public.notify_order_created();

CREATE OR REPLACE FUNCTION public.notify_coupon_redeemed() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId","orderId")
 VALUES ('club','coupon_redeemed','redemption:'||NEW.id,NEW."userId",NEW."orderId")
 ON CONFLICT ("sourceKey") DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_coupon_redeemed() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_coupon_redemption ON public."CouponRedemption";
CREATE TRIGGER admin_notify_coupon_redemption AFTER INSERT ON public."CouponRedemption"
 FOR EACH ROW EXECUTE FUNCTION public.notify_coupon_redeemed();

CREATE OR REPLACE FUNCTION public.notify_loyalty_event() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 INSERT INTO public."AdminNotification" ("category","kind","sourceKey","userId","orderId")
 VALUES ('club',
 CASE WHEN NEW.kind='EARN' THEN 'points_earned'
      WHEN NEW.kind='SPEND' THEN 'points_spent'
      WHEN NEW.kind='REFUND_SPEND_RESTORE' THEN 'points_restored'
      ELSE 'points_adjusted' END,
 'loyalty:'||NEW.id,NEW."userId",NEW."orderId")
 ON CONFLICT ("sourceKey") DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_loyalty_event() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_loyalty ON public."LoyaltyEntry";
CREATE TRIGGER admin_notify_loyalty AFTER INSERT ON public."LoyaltyEntry"
 FOR EACH ROW EXECUTE FUNCTION public.notify_loyalty_event();

CREATE OR REPLACE FUNCTION public.notify_refund_recorded() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE order_id INTEGER;
BEGIN
 SELECT i."orderId" INTO order_id FROM public."InvoiceCorrection" c
  JOIN public."Invoice" i ON i.id=c."invoiceId"
  WHERE c.id=NEW."correctionId";
 INSERT INTO public."AdminNotification" ("category","kind","sourceKey","orderId")
 VALUES ('orders','refund_recorded','refund:'||NEW."correctionId",order_id)
 ON CONFLICT ("sourceKey") DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.notify_refund_recorded() FROM PUBLIC;
DROP TRIGGER IF EXISTS admin_notify_refund ON public."InvoiceRefund";
CREATE TRIGGER admin_notify_refund AFTER INSERT ON public."InvoiceRefund"
 FOR EACH ROW EXECUTE FUNCTION public.notify_refund_recorded();
